cd /tmp/opensip-implementation/m1-protocol-gap-resolution-01 && /tmp/opensip-implementation/metadata-reference-env/bin/python -I -B -c '
import json
d=json.load(open("resolutions.json"))
def walk(o):
  if isinstance(o,dict):
    if o.get("gap") in ("AUDIT-G10",) or any(str(v).startswith(("P-5","UQ-1")) for k,v in o.items() if k in ("id","gap")):
      print(json.dumps(o,indent=1))
    for v in o.values(): walk(v)
  elif isinstance(o,list):
    for v in o: walk(v)
walk(d)'; grep -n -B2 -A25 -E "P-5|UQ-1|AUDIT-G10" resolutions.md | head -150

cd /Users/sb/code/opensip-ai/opensip_arch/docs/implementation/m1/metadata-v2 && /tmp/opensip-implementation/metadata-reference-env/bin/python -I -B -c '
import json
d=json.load(open("command-inventory.v4.json"))
print(list(d.keys()))
for k,v in d.items():
  if isinstance(v,list): print(k,len(v), json.dumps(v[0])[:600] if v else "")
  elif isinstance(v,dict): print(k, list(v.keys())[:40])
  else: print(k,v)
'

