"""Product envelope canonicalization reference; design evidence, not a host runtime."""
import hashlib
import json
from jsonschema import Draft202012Validator, ValidationError, validators

MIN_INT, MAX_INT = -(2**63), 2**64 - 1
MAX_BYTES, MAX_DEPTH = 4 * 1024 * 1024, 32

class AdmissionError(ValueError):
    pass

def typed(value, depth=0):
    if type(value) in (dict, list) and depth >= MAX_DEPTH:
        raise AdmissionError('DEPTH_LIMIT')
    if value is None or type(value) is bool:
        return
    if type(value) is int:
        if not MIN_INT <= value <= MAX_INT:
            raise AdmissionError('INTEGER_RANGE')
        return
    if type(value) is str:
        try:
            value.encode('utf-8', 'strict')
        except UnicodeError as exc:
            raise AdmissionError('UNICODE_SCALAR_REQUIRED') from exc
        return
    if type(value) is list:
        for child in value:
            typed(child, depth + 1)
        return
    if type(value) is dict:
        for key, child in value.items():
            if type(key) is not str:
                raise AdmissionError('STRING_KEY_REQUIRED')
            typed(key, depth + 1)
            typed(child, depth + 1)
        return
    raise AdmissionError('EXACT_JSON_TYPE_REQUIRED')

def parse(raw):
    if type(raw) is not bytes or len(raw) > MAX_BYTES:
        raise AdmissionError('BYTE_LIMIT_OR_TYPE')
    def pairs(items):
        result = {}
        for key, value in items:
            if key in result:
                raise AdmissionError('DUPLICATE_KEY')
            result[key] = value
        return result
    def integer(text):
        if text == '-0':
            raise AdmissionError('NEGATIVE_ZERO')
        value = int(text)
        if not MIN_INT <= value <= MAX_INT:
            raise AdmissionError('INTEGER_RANGE')
        return value
    def forbidden(_):
        raise AdmissionError('FLOAT_OR_NONFINITE_FORBIDDEN')
    try:
        value = json.loads(raw.decode('utf-8','strict'), object_pairs_hook=pairs,
                           parse_int=integer, parse_float=forbidden, parse_constant=forbidden)
        typed(value)
        return value
    except (UnicodeError, ValueError, RecursionError) as exc:
        raise AdmissionError(str(exc)) from exc

def canonical(value):
    typed(value)
    # UTF-8 lexicographic key order equals Unicode scalar-value order for valid strings.
    raw = json.dumps(value, ensure_ascii=False, sort_keys=True,
                     separators=(',', ':'), allow_nan=False).encode('utf-8')
    if len(raw) > MAX_BYTES:
        raise AdmissionError('BYTE_LIMIT')
    return raw

def identity(domain, value):
    if not domain or not all(c in 'abcdefghijklmnopqrstuvwxyz0123456789-.' for c in domain):
        raise AdmissionError('DOMAIN')
    raw = canonical(value)
    preimage = b'opensip.product.v1\0' + domain.encode('ascii') + b'\0' + len(raw).to_bytes(8,'big') + raw
    return hashlib.sha256(preimage).hexdigest()

def equal_typed(a, b):
    if type(a) is not type(b):
        return False
    if type(a) is dict:
        return a.keys() == b.keys() and all(equal_typed(a[k], b[k]) for k in a)
    if type(a) is list:
        return len(a) == len(b) and all(equal_typed(x,y) for x,y in zip(a,b))
    return a == b

def exact_const(validator, expected, instance, schema):
    if not equal_typed(expected, instance):
        yield ValidationError('exact const type/value mismatch')

def exact_enum(validator, expected, instance, schema):
    if not any(equal_typed(x,instance) for x in expected):
        yield ValidationError('exact enum type/value mismatch')

def exact_order(validator, order, instance, schema):
    """Admission owns semantic order; canonical encoding preserves every array."""
    if type(instance) is not list or order == 'sequence':
        return
    try:
        if type(order) is dict:
            if set(order) != {'by'} or type(order['by']) is not list or not order['by'] or any(type(k) is not str or not k for k in order['by']) or len(set(order['by'])) != len(order['by']):
                raise ValueError('invalid field-order annotation')
            keys = [tuple(v[k].encode('utf-8') for k in order['by']) for v in instance]
        elif order == 'utf8':
            keys = [v.encode('utf-8') for v in instance]
        elif order in ('canonical-set', 'canonical-order'):
            keys = [canonical(v) for v in instance]
        elif order in ('path', 'ruleId', 'waiverId'):
            keys = [v[order].encode('utf-8') for v in instance]
        elif order == 'predicate':
            keys = [tuple(v[k].encode('utf-8') for k in ('ruleId','subjectId','predicateId')) for v in instance]
        elif order == 'numeric':
            if any(type(v) is not int for v in instance):
                raise ValueError('integer order required')
            keys = instance
        elif order == 'ordinal':
            keys = [v['ordinal'] for v in instance]
            if any(type(v) is not int for v in keys) or keys != list(range(len(keys))):
                raise ValueError('contiguous ordinal required')
        elif order == 'candidateOrdinal':
            # Published in native/occupancy-companion.schema.v1.json
            # x-opensip-order-vocabulary. Integer unique strictly increasing.
            # Not contiguous 0..n-1 (separate FactBatch candidate-stream law).
            keys = [v['candidateOrdinal'] for v in instance]
            if any(type(v) is not int for v in keys):
                raise ValueError('integer candidateOrdinal required')
        else:
            raise ValueError('unregistered order annotation')
        if keys != sorted(keys) or (order != 'canonical-order' and len(keys) != len(set(keys))):
            raise ValueError('canonical nondecreasing order required' if order == 'canonical-order' else 'strict unique order required')
    except (KeyError, TypeError, AttributeError, ValueError) as exc:
        yield ValidationError('array order '+str(order)+': '+str(exc))

ExactValidator = validators.extend(Draft202012Validator,
    validators={'const':exact_const, 'enum':exact_enum, 'x-opensip-order':exact_order},
    type_checker=Draft202012Validator.TYPE_CHECKER.redefine('integer',lambda checker, value:type(value) is int))

def validate(schema, value, registry=None):
    typed(value)
    if registry is None:
        ExactValidator(schema).validate(value)
    else:
        ExactValidator(schema, registry=registry).validate(value)
    return value
"""Reference validation of the scoped metadata correction; no product qualification."""
import argparse
import copy
import hashlib
import importlib.util
import json
from pathlib import Path
from referencing import Registry, Resource
from referencing.jsonschema import DRAFT202012
from jsonschema import Draft202012Validator

HERE = Path(__file__).resolve().parent


def read(path):
    return json.loads(path.read_bytes())


def verify_successor(arch):
    record = read(HERE / "successor.json")
    prefix = "docs/implementation/m1/metadata-v2/"
    assert {Path(pin["path"]).name for pin in record["candidates"]} == {p.name for p in HERE.iterdir() if p.is_file() and p.name != "successor.json"}
    for pin in record["candidates"]:
        assert pin["path"] == prefix + Path(pin["path"]).name
        raw = (HERE / Path(pin["path"]).name).read_bytes()
        assert len(raw) == pin["bytes"] and hashlib.sha256(raw).hexdigest() == pin["sha256"], pin["path"]
    parents = {pin["path"]: pin for pin in record["parents"]}
    for pin in parents.values():
        raw = (arch / pin["path"]).read_bytes()
        assert len(raw) == pin["bytes"] and hashlib.sha256(raw).hexdigest() == pin["sha256"], pin["path"]
    assert len(record["passageOverrides"]) == 4
    for override in record["passageOverrides"]:
        pin = override["parent"]
        assert parents[pin["path"]] == pin
        path = arch / pin["path"]
        selector = override["selector"]
        if "line" in selector:
            value = path.read_text().splitlines()[selector["line"] - 1]
        else:
            value = read(path)
            for key in selector["jsonPointer"].strip("/").split("/"):
                value = value[int(key)] if isinstance(value, list) else value[key]
        assert value == override["before"]
        assert override["after"] == value.replace("build-embedded signed release descriptor", "build-embedded metadata covered by the enclosing signed host/release artifact")


def load(arch):
    sources = read(HERE / "sources.json")
    def checked(pin):
        source = HERE / Path(pin["path"]).name if pin["path"].startswith("docs/implementation/m1/metadata-v2/") else arch / pin["path"]
        raw = source.read_bytes()
        assert len(raw) == pin["bytes"] and hashlib.sha256(raw).hexdigest() == pin["sha256"], pin["path"]
        return raw
    lexical = sources["lexicalReference"]
    checked(lexical)
    spec = importlib.util.spec_from_file_location("canonical_reference", arch / lexical["path"])
    reference = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(reference)
    documents = {}
    for pin in sources["schemas"]:
        schema = reference.parse(checked(pin))
        Draft202012Validator.check_schema(schema)
        assert schema["$id"] not in documents
        documents[schema["$id"]] = schema
    # No retrieval hook: any unregistered document reference refuses offline.
    # jsonschema.evolve selects the standard validator when a referenced resource
    # retains $schema. Keep the verified 2020-12 dialect explicit in Resource,
    # omitting only its dispatch annotation so ExactValidator survives $ref.
    assert all(schema.get("$schema") == "https://json-schema.org/draft/2020-12/schema" for schema in documents.values())
    registry = Registry().with_resources((key, Resource(contents={k: v for k, v in schema.items() if k != "$schema"}, specification=DRAFT202012)) for key, schema in documents.items())
    return reference, registry, documents


def admit_build(reference, registry, build, asset_channel):
    reference.validate({"$ref": "urn:opensip:product-v1:workflows:metadata:1#/$defs/BuildMetadataV1"}, build, registry)
    assert asset_channel == build["buildChannel"], "HostAssetPinV1 and BuildMetadataV1 channels disagree"


def admit(reference, registry, envelope_schema, value, catalogue, build):
    reference.validate(envelope_schema, value, registry)
    exit_codes = {"success": 0, "policy-failed": 1, "request-rejected": 2, "indeterminate": 3, "operational-failed": 4, "interrupted": 130}
    assert value["exitCode"] == exit_codes[value["termination"]["class"]], "termination/exit mismatch"
    if value["kind"] != "meta":
        return
    meta = value["meta"]
    if meta["command"] == "help":
        selected = catalogue if meta["topic"] is None else [row for row in catalogue if row["name"] == meta["topic"]]
        assert selected and reference.equal_typed(meta["commands"], selected), "metadata differs from compiled catalogue"
    else:
        expected = {"command": "version", **{key: val for key, val in build.items() if key != "schemaVersion"}}
        assert reference.equal_typed(meta, expected), "metadata differs from admitted compiled build selection"


def compatibility(arch, current):
    base = read(arch / "docs/coop/design-corrections/workflows/schemas/evaluator3/command-envelope.schema.json")
    restored = copy.deepcopy(current)
    for key in ("$id", "title", "description"):
        restored[key] = base[key]
    restored["properties"]["schemaMajor"]["const"] = 3
    restored["properties"]["kind"]["enum"].remove("meta")
    del restored["properties"]["meta"]
    restored["properties"]["errors"]["minItems"] = 1
    assert len(restored["allOf"]) == len(base["allOf"]) + 2
    restored["allOf"] = restored["allOf"][:-2]
    assert restored == base, "unexpected existing envelope constraint change"
    allowed = {"schemaFamily", "schemaMajor", "kind", "requestId", "clientCorrelationId", "termination", "exitCode", "meta"}
    excluded = {row["required"][0] for row in current["allOf"][-2]["then"]["not"]["anyOf"]}
    assert excluded == set(current["properties"]) - allowed


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--architecture", required=True, type=Path)
    args = parser.parse_args()
    verify_successor(args.architecture)
    reference, registry, documents = load(args.architecture)
    eid = "urn:opensip:product-v1:workflows:evaluator3:command-envelope:4"
    envelope = documents[eid]
    compatibility(args.architecture, envelope)
    fixture = read(HERE / "fixtures.json")
    metadata_id = "urn:opensip:product-v1:workflows:metadata:1"
    admit_build(reference, registry, fixture["build"], fixture["assetBuildChannel"])
    try:
        admit_build(reference, registry, fixture["build"], "release")
    except AssertionError as exc:
        assert "channels disagree" in str(exc)
    else:
        raise AssertionError("mismatched HostAssetPinV1 channel accepted")
    catalogue_names = [row["name"] for row in fixture["catalogue"]]
    assert catalogue_names == sorted(set(catalogue_names))
    results = []
    for case in fixture["cases"]:
        reason = None
        try:
            admit(reference, registry, envelope, case["value"], fixture["catalogue"], fixture["build"])
        except Exception as exc:
            # Record exact exception; unexpected exceptions are not accepted refusals.
            from jsonschema import ValidationError
            if not isinstance(exc, (ValidationError, AssertionError, reference.AdmissionError)):
                raise
            reason = type(exc).__name__ + ": " + str(exc).splitlines()[0]
        assert (reason is None) == case["accepted"], (case["id"], reason)
        results.append({"id": case["id"], "accepted": reason is None, "reason": reason})
    for case_id in ("unsorted-help", "duplicate-help-name", "invented-development-closure"):
        value = next(case["value"] for case in fixture["cases"] if case["id"] == case_id)
        assert not reference.ExactValidator(envelope, registry=registry).is_valid(value), case_id + " shape must refuse through external-root reference"
    # Explicit unknown refs fail rather than performing retrieval.
    for target in ("https://example.invalid/schema", "file:///tmp/schema.json", "../schema.json"):
        try:
            reference.validate({"$ref": target}, {}, registry)
        except Exception as exc:
            from jsonschema.exceptions import _WrappedReferencingError
            assert isinstance(exc, _WrappedReferencingError)
        else:
            raise AssertionError("unregistered reference accepted")
    # All old valid branches still select major3, and reject any major4 wire value.
    old = documents[eid.replace(":4", ":3")]
    for case in fixture["cases"]:
        if case["accepted"]:
            assert not reference.ExactValidator(old, registry=registry).is_valid(case["value"])
    inventory = read(HERE / "command-inventory.v4.json")
    reference.validate(documents["urn:opensip:product-v1:workflows:evaluator3:command-inventory:4"], inventory, registry)
    coverage = read(HERE / "implementation-coverage.v2.json")
    for group in coverage["groups"].values():
        for row in group:
            source = row.get("source", {})
            if source.get("key") == "commands":
                selected = inventory
                for key in source["selector"].strip("/").split("/"):
                    selected = selected[int(key)] if isinstance(selected, list) else selected[key]
                assert hashlib.sha256(reference.canonical(selected)).hexdigest() == source["valueSha256"]
    # Selected old failure behavior survives unchanged after the major advance.
    format_failure = next(case["value"] for case in fixture["cases"] if case["id"] == "completion-format-refusal")
    reference.validate(old, {**format_failure, "schemaMajor": 3}, registry)
